26sp/5.1.solution:
private static boolean isLocalPeak(int[][] grid, int r, int c) {
    int val = grid[r][c];
    int n = grid.length;
    return (r <= 0 || val > grid[r - 1][c]) &&
           (r >= n - 1 || val > grid[r + 1][c]) &&
           (c <= 0 || val > grid[r][c - 1]) &&
           (c >= n - 1 || val > grid[r][c + 1]);
}

public static int countLocalPeaks(int[][] grid) {
    int count = 0;
    for (int r = 0; r < grid.length; r++)
        for (int c = 0; c < grid.length; c++)
            if (isLocalPeak(grid, r, c)) count++;
    return count;
}

