public static int[] columnSums(int[][] grid) {
    int width = 0;
    for (int i = 0; i < grid.length; i++) {
        if (grid[i] != null && grid[i].length > width) {
            width = grid[i].length;
        }
    }
    int[] sums = new int[width];
    for (int i = 0; i < grid.length; i++) {
        if (grid[i] == null) {
            continue;
        }
        for (int j = 0; j < grid[i].length; j++) {
            sums[j] += grid[i][j];
        }
    }
    return sums;
}

