// return an m x n reshaped array if possible, null otherwise
public static int[][] reshape(int[] input, int m, int n) {
    if (input.length <= (m - 1) * n || input.length > m * n) {
        return null;
    }
    int[][] result = new int[m][n];
    int curr = 0;
    for (int row = 0; row < m; row++) {
        for (int col = 0; col < n && curr < input.length; col++) {
            result[row][col] = input[curr];
            curr++;
        }
    }
    return result;
}

