private static boolean isSubArray(int[][] small, int[][] big,
                                  int row, int col) {
    int m = small.length;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            if (small[i][j] != big[row + i][col + j]) {
                return false;
            }
        }
    }
    return true;
}

public static int numberOfAppearances(int[][] small, int[][] big) {
    int m = small.length;
    int n = big.length;
    int count = 0;
    for (int i = 0; i <= n - m; i++) {
        for (int j = 0; j <= n - m; j++) {
            if (isSubArray(small, big, i, j)) {
                count++;
            }
        }
    }
    return count;
}

