// -1 when (r, c) is outside the grid; values are positive, so -1 never blocks a peak.
private static int lookup(int[][] grid, int r, int c) {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[r].length) {
        return -1;
    }
    return grid[r][c];
}

private static boolean isLocalPeak(int[][] grid, int r, int c) {
    int val = grid[r][c];
    return val > lookup(grid, r - 1, c) && val > lookup(grid, r + 1, c)
        && val > lookup(grid, r, c - 1) && val > lookup(grid, r, c + 1);
}

public static int countLocalPeaks(int[][] grid) {
    int peakCount = 0;
    for (int r = 0; r < grid.length; r++)
        for (int c = 0; c < grid[r].length; c++)
            if (isLocalPeak(grid, r, c)) peakCount++;
    return peakCount;
}

